#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::path::PathBuf;

    fn fixtures_dir() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("fixtures")
    }

    fn read_fixture(name: &str) -> String {
        fs::read_to_string(fixtures_dir().join(name)).unwrap()
    }

    #[test]
    fn allow_fixture_applies() {
        let input = parse_fixture_text(&read_fixture("allow.gaplune"));
        assert_eq!(input.walls.is_empty(), false);
        assert_eq!(input.walls.iter().any(|w| w.closed), false);
        let mut hits = 0;
        let result = envelope_cross(input, &mut hits);
        assert_eq!(result.allow, true);
        assert_eq!(result.applied, true);
        assert_eq!(hits, 1);
        assert_eq!(result.closed.is_empty(), true);
    }

    #[test]
    fn one_closed_wall_skips_apply() {
        let input = parse_fixture_text(&read_fixture("one-closed-wall.gaplune"));
        assert_eq!(input.walls.iter().filter(|w| w.closed).count(), 1);
        let mut hits = 0;
        let result = envelope_cross(input, &mut hits);
        assert_eq!(result.allow, false);
        assert_eq!(result.applied, false);
        assert_eq!(hits, 0);
        assert_eq!(result.closed.len(), 1);
        assert_eq!(result.closed[0].id.as_str(), "writing:no_em_dashes");
    }

    #[test]
    fn n_closed_walls_collect_all_and_skip_apply() {
        let input = parse_fixture_text(&read_fixture("n-closed-walls.gaplune"));
        let closed_n = input.walls.iter().filter(|w| w.closed).count();
        assert_eq!(closed_n >= 5, true);
        let mut hits = 0;
        let result = envelope_cross(input, &mut hits);
        assert_eq!(result.allow, false);
        assert_eq!(result.applied, false);
        assert_eq!(hits, 0);
        assert_eq!(result.closed.len(), closed_n);
        let ids: Vec<&str> = result.closed.iter().map(|w| w.id.as_str()).collect();
        assert_eq!(ids.contains(&"lattice.unknown_path"), true);
        assert_eq!(ids.contains(&"writing:no_em_dashes"), true);
        assert_eq!(ids.contains(&WALL_TRUST_FLOOR), true);
        assert_eq!(ids.contains(&WALL_CHANNEL_NON_FRAME), true);
        assert_eq!(ids.contains(&WALL_TEMPORAL_DRIFT), true);
    }

    #[test]
    fn order_permutation_keeps_closed_set_key() {
        let a = parse_fixture_text(&read_fixture("order-permutation-a.gaplune"));
        let b = parse_fixture_text(&read_fixture("order-permutation-b.gaplune"));
        let mut hits_a = 0;
        let mut hits_b = 0;
        let left = envelope_cross(a, &mut hits_a);
        let right = envelope_cross(b, &mut hits_b);
        assert_eq!(left.key, right.key);
        assert_eq!(left.allow, right.allow);
        assert_eq!(left.applied, false);
        assert_eq!(right.applied, false);
        assert_eq!(hits_a, 0);
        assert_eq!(hits_b, 0);
        assert_eq!(left.closed.len() >= 5, true);
    }

    #[test]
    fn compiled_dimensions_shuffle_keeps_key() {
        let lattice_closed = vec![AdmitWall::close(
            "lattice.unknown_path",
            "Unknown action path",
        )];
        let mut walls_a = compile_envelope_walls(
            &lattice_closed,
            &em_sample(),
            1,
            5,
            &closed_frame_channel(),
            &closed_temporal(),
        );
        let mut walls_b = walls_a.clone();
        walls_b.reverse();
        let mut hits_a = 0;
        let mut hits_b = 0;
        let left = envelope_cross(EnvelopeInput { walls: walls_a.clone() }, &mut hits_a);
        let right = envelope_cross(EnvelopeInput { walls: walls_b }, &mut hits_b);
        assert_eq!(left.key, right.key);
        assert_eq!(left.allow, false);
        assert_eq!(left.applied, false);
        assert_eq!(hits_a, 0);
        assert_eq!(hits_b, 0);
        let ids: Vec<&str> = left.closed.iter().map(|w| w.id.as_str()).collect();
        assert_eq!(ids.contains(&"lattice.unknown_path"), true);
        assert_eq!(ids.iter().any(|id| id.starts_with("writing:")), true);
        assert_eq!(ids.contains(&WALL_TRUST_FLOOR), true);
        assert_eq!(ids.contains(&WALL_CHANNEL_NON_FRAME), true);
        assert_eq!(ids.contains(&WALL_TEMPORAL_DRIFT), true);
        walls_a.clear();
    }

    #[test]
    fn compiled_allow_applies() {
        let lattice_open = vec![AdmitWall::open("lattice.known_path")];
        let walls = compile_envelope_walls(
            &lattice_open,
            "plain hyphen-ok prose",
            3,
            1,
            &open_frame_channel(),
            &open_temporal(),
        );
        let mut hits = 0;
        let result = envelope_cross(EnvelopeInput { walls }, &mut hits);
        assert_eq!(result.allow, true);
        assert_eq!(result.applied, true);
        assert_eq!(hits, 1);
    }

    #[test]
    fn apply_skip_module_skips_when_admit_fails() {
        let mut gate = apply_skip::ApplySkip::new();
        gate.admit_allow = false;
        gate.process().unwrap();
        assert_eq!(gate.applied, false);
        gate.admit_allow = true;
        gate.process().unwrap();
        assert_eq!(gate.applied, true);
    }
}
